-- init
SET client_encoding=UTF8;

CREATE TABLE nlssort_utf8(id serial, val varchar(8));


-- test collation
select id, val, nlssort(val, 'nls_sort=binary')              from nlssort_utf8 order by nlssort(val, 'nls_sort=BINARY'), id;
select id, val, nlssort(val, 'nls_sort=binary_ai')           from nlssort_utf8 order by nlssort(val, 'nls_sort=BINARY_AI'), id;
select id, val, nlssort(val, 'nls_sort=binary_ci')           from nlssort_utf8 order by nlssort(val, 'nls_sort=BINARY_CI'), id;
select id, val, nlssort(val, 'nls_sort=generic_m_ci')        from nlssort_utf8 order by nlssort(val, 'nls_sort=GENERIC_M_CI'), id;
select id, val, nlssort(val, 'nls_sort=schinese_pinyin_m')   from nlssort_utf8 order by nlssort(val, 'nls_sort=SCHINESE_PINYIN_M'), id;
select id, val, nlssort(val, 'nls_sort=schinese_stroke_m')   from nlssort_utf8 order by nlssort(val, 'nls_sort=SCHINESE_STROKE_M'), id;
select id, val, nlssort(val, 'nls_sort=schinese_radical_m')  from nlssort_utf8 order by nlssort(val, 'nls_sort=SCHINESE_RADICAL_M'), id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese')    from nlssort_utf8 order by nlssort(val, 'nls_sort=UCA0700_SCHINESE'), id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese1')   from nlssort_utf8 order by nlssort(val, 'nls_sort=UCA0700_SCHINESE1'), id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese2')   from nlssort_utf8 order by nlssort(val, 'nls_sort=UCA0700_SCHINESE2'), id;

-- test collate
select id, val, nlssort(val, 'nls_sort=binary')              from nlssort_utf8 order by val collate BINARY, id;
select id, val, nlssort(val, 'nls_sort=binary_ai')           from nlssort_utf8 order by val collate BINARY_AI, id;
select id, val, nlssort(val, 'nls_sort=binary_ci')           from nlssort_utf8 order by val collate BINARY_CI, id;
select id, val, nlssort(val, 'nls_sort=generic_m_ci')        from nlssort_utf8 order by val collate GENERIC_M_CI, id;
select id, val, nlssort(val, 'nls_sort=schinese_pinyin_m')   from nlssort_utf8 order by val collate SCHINESE_PINYIN_M, id;
select id, val, nlssort(val, 'nls_sort=schinese_stroke_m')   from nlssort_utf8 order by val collate SCHINESE_STROKE_M, id;
select id, val, nlssort(val, 'nls_sort=schinese_radical_m')  from nlssort_utf8 order by val collate SCHINESE_RADICAL_M, id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese')    from nlssort_utf8 order by val collate UCA0700_SCHINESE, id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese1')   from nlssort_utf8 order by val collate UCA0700_SCHINESE1, id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese2')   from nlssort_utf8 order by val collate UCA0700_SCHINESE2, id;

-- test pesudo-collation, just do syntax check
CREATE TABLE test(val varchar2(64));

SET NLS_COMP = BINARY;
select val from test order by val collate USING_NLS_COMP; -- BINARY

SET NLS_COMP = LINGUISTIC;
SET NLS_SORT = SCHINESE_PINYIN_M;
select val from test order by val collate USING_NLS_COMP; -- SCHINESE_PINYIN_M

SET NLS_COMP = ANSI;
SET NLS_SORT = SCHINESE_PINYIN_M;
select val from test order by val collate USING_NLS_COMP; -- SCHINESE_PINYIN_M

SET NLS_SORT = BINARY;
select val from test order by val collate USING_NLS_SORT;    -- BINARY
select val from test order by val collate USING_NLS_SORT_AI; -- BINARY_AI
select val from test order by val collate USING_NLS_SORT_CI; -- BINARY_CI
select val from test order by val collate USING_NLS_SORT_CS; -- BINARY

SET NLS_SORT = BINARY_AI;
select val from test order by val collate USING_NLS_SORT;    -- BINARY_AI
select val from test order by val collate USING_NLS_SORT_AI; -- BINARY_AI
select val from test order by val collate USING_NLS_SORT_CI; -- BINARY_AI
select val from test order by val collate USING_NLS_SORT_CS; -- BINARY

SET NLS_SORT = BINARY_CI;
select val from test order by val collate USING_NLS_SORT;    -- BINARY_CI
select val from test order by val collate USING_NLS_SORT_AI; -- BINARY_AI
select val from test order by val collate USING_NLS_SORT_CI; -- BINARY_CI
select val from test order by val collate USING_NLS_SORT_CS; -- BINARY

SET NLS_SORT = SCHINESE_PINYIN_M;
select val from test order by val collate USING_NLS_SORT;    -- SCHINESE_PINYIN_M
select val from test order by val collate USING_NLS_SORT_AI; -- error
select val from test order by val collate USING_NLS_SORT_CI; -- error
select val from test order by val collate USING_NLS_SORT_CS; -- SCHINESE_PINYIN_M

DROP TABLE test;
DROP TABLE nlssort_utf8;